const FONT_LINK = "https://fonts.googleapis.com/css2?family=Zen+Kaku+Gothic+New:wght@500;700;900&family=Noto+Sans+TC:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap";
function useInjectFonts() {
  useEffect(() => {
    if (!document.getElementById("pp-fonts")) {
      const link = document.createElement("link");
      link.id = "pp-fonts";
      link.rel = "stylesheet";
      link.href = FONT_LINK;
      document.head.appendChild(link);
    }
  }, []);
}

/* ------------------------- Persistent storage ------------------------- */

const STORAGE_KEY = "procure-v2-appdata";

function useAppData(seed) {
  const [data, setData] = useState(seed);
  const [loaded, setLoaded] = useState(false);
  const [saveState, setSaveState] = useState("idle"); // idle | saving | saved | error | synced-remote
  const skipNextSave = useRef(false);

  const load = async () => {
    try {
      const res = await window.storage.get(STORAGE_KEY, false);
      if (res && res.value) {
        const parsed = JSON.parse(res.value);
        skipNextSave.current = true;
        setData({ ...seed, ...parsed });
      }
    } catch (e) {
      // no saved data yet — use seed
    } finally {
      setLoaded(true);
    }
  };

  useEffect(() => { load(); }, []);

  // If the storage layer supports realtime (e.g. Supabase-backed shim in main.jsx),
  // it dispatches this event when another browser/device changes the shared data.
  useEffect(() => {
    const onRemoteUpdate = (e) => {
      if (e.detail?.key !== STORAGE_KEY || !e.detail?.value) return;
      try {
        const parsed = JSON.parse(e.detail.value);
        skipNextSave.current = true;
        setData({ ...seed, ...parsed });
        setSaveState("synced-remote");
        setTimeout(() => setSaveState("saved"), 2000);
      } catch (err) { /* ignore malformed remote payload */ }
    };
    window.addEventListener("storage-remote-update", onRemoteUpdate);
    return () => window.removeEventListener("storage-remote-update", onRemoteUpdate);
  }, []);

  useEffect(() => {
    if (!loaded) return;
    if (skipNextSave.current) { skipNextSave.current = false; return; }
    setSaveState("saving");
    const t = setTimeout(async () => {
      try {
        await window.storage.set(STORAGE_KEY, JSON.stringify(data), false);
        setSaveState("saved");
      } catch (e) {
        setSaveState("error");
      }
    }, 500);
    return () => clearTimeout(t);
  }, [data, loaded]);

  return [data, setData, loaded, saveState, load];
}

