/* ------------------------- Excel helpers ------------------------- */

function downloadWorkbook(filename, sheets) {
  const wb = XLSX.utils.book_new();
  sheets.forEach(({ name, headers, rows }) => {
    const aoa = [headers, ...rows];
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    XLSX.utils.book_append_sheet(wb, ws, name);
  });
  const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
  const blob = new Blob([wbout], { type: "application/octet-stream" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function parseExcelFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: "array" });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });
        const headers = (rows[0] || []).map((h) => String(h).trim());
        const body = rows.slice(1).filter((r) => r.some((c) => String(c).trim() !== ""));
        resolve({ headers, rows: body });
      } catch (err) { reject(err); }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
}

function guessColumn(headers, keywords) {
  const idx = headers.findIndex((h) => keywords.some((k) => h.includes(k)));
  return idx >= 0 ? idx : "";
}

/* ------------------------- Small UI atoms ------------------------- */

function Badge({ children, tint = "#2F6FED", soft = true }) {
  return (
    <span style={{ background: soft ? `${tint}18` : tint, color: soft ? tint : "#fff" }}
      className="px-2.5 py-1 rounded-full text-xs font-semibold inline-flex items-center gap-1 whitespace-nowrap">
      {children}
    </span>
  );
}

function KPICard({ label, value, unit, delta, up, icon: Icon, tint }) {
  return (
    <div className="rounded-2xl p-5 bg-white" style={{ border: "1px solid #E7EAF3" }}>
      <div className="flex items-center justify-between mb-4">
        <div className="w-10 h-10 rounded-xl flex items-center justify-center" style={{ background: `${tint}16` }}>
          <Icon size={19} color={tint} strokeWidth={2.1} />
        </div>
        {delta && (
          <span className="text-[11px] font-semibold flex items-center gap-1" style={{ color: up ? "#0E9F8E" : "#E0932B" }}>
            {up ? <TrendingUp size={12} /> : <TrendingDown size={12} />} {delta}
          </span>
        )}
      </div>
      <div className="text-xs mb-1.5" style={{ color: "#64708A" }}>{label}</div>
      <div className="flex items-baseline gap-1">
        <span style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-[1.7rem] font-semibold">{value}</span>
        {unit && <span className="text-xs" style={{ color: "#8891A6" }}>{unit}</span>}
      </div>
    </div>
  );
}

function SaveIndicator({ state }) {
  const map = {
    idle: ["", "#8891A6"],
    saving: ["儲存中…", "#8891A6"],
    saved: ["已同步", "#0E9F8E"],
    error: ["儲存失敗（請檢查網路連線或雲端資料庫設定）", "#E0524B"],
    "synced-remote": ["偵測到其他裝置的更新，已同步最新資料", "#2F6FED"],
  };
  const [label, color] = map[state] || map.idle;
  if (!label) return null;
  return <span className="text-[11px] font-medium" style={{ color }}>{label}</span>;
}

