function Sidebar({ active, setActive, recordCount, user, onSignOut }) {
  return (
    <aside className="w-64 shrink-0 h-screen sticky top-0 flex flex-col print:hidden" style={{ background: "#10213D" }}>
      <div className="flex items-center gap-3 px-6 py-6">
        <div className="w-9 h-9 rounded-lg flex items-center justify-center" style={{ background: "linear-gradient(135deg,#2F6FED,#7C5CFC)" }}>
          <Store size={18} color="#fff" strokeWidth={2.3} />
        </div>
        <div style={{ fontFamily: "'Zen Kaku Gothic New', sans-serif" }} className="text-white font-bold text-[15px] leading-tight">
          連鎖店採購中控台
        </div>
      </div>

      <nav className="flex-1 px-3 mt-3 space-y-1">
        {NAV_ITEMS.map((item) => {
          const isActive = active === item.key;
          const Icon = item.icon;
          return (
            <button key={item.key} onClick={() => setActive(item.key)}
              className="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-sm transition-colors relative"
              style={{ background: isActive ? "rgba(47,111,237,0.16)" : "transparent", color: isActive ? "#7FA8FF" : "rgba(255,255,255,0.62)" }}>
              {isActive && <span className="absolute left-0 top-1.5 bottom-1.5 w-[3px] rounded-full" style={{ background: "#2F6FED" }} />}
              <Icon size={17} strokeWidth={2.1} />
              <span className="font-medium">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="mx-3 mb-3 p-3 rounded-xl" style={{ background: "rgba(255,255,255,0.06)" }}>
        <div className="text-white/40 text-[10px] mb-1">目前累積進貨紀錄</div>
        <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-white text-lg font-bold">{recordCount.toLocaleString()} 筆</div>
      </div>

      {user && (
        <div className="mx-3 mb-5 p-3 rounded-xl flex items-center gap-2.5" style={{ background: "rgba(255,255,255,0.06)" }}>
          <div className="w-7 h-7 rounded-full flex items-center justify-center text-white text-[11px] font-bold shrink-0" style={{ background: "#2F6FED" }}>
            {(user.email || "?").slice(0, 1).toUpperCase()}
          </div>
          <div className="flex-1 min-w-0">
            <div className="text-white text-xs font-medium truncate">{user.email}</div>
          </div>
          {onSignOut && (
            <button onClick={onSignOut} title="登出" className="shrink-0">
              <LogOut size={15} color="rgba(255,255,255,0.5)" />
            </button>
          )}
        </div>
      )}
    </aside>
  );
}

function Topbar({ title, subtitle, saveState, onRefresh }) {
  const [refreshing, setRefreshing] = useState(false);
  const doRefresh = async () => {
    setRefreshing(true);
    await onRefresh();
    setTimeout(() => setRefreshing(false), 500);
  };
  return (
    <div className="flex items-center justify-between px-8 py-5 sticky top-0 z-10 backdrop-blur print:hidden"
      style={{ background: "rgba(246,247,251,0.85)", borderBottom: "1px solid #E7EAF3" }}>
      <div>
        <h1 style={{ fontFamily: "'Zen Kaku Gothic New', sans-serif" }} className="text-xl font-bold">{title}</h1>
        {subtitle && <p className="text-xs mt-0.5" style={{ color: "#64708A" }}>{subtitle}</p>}
      </div>
      <div className="flex items-center gap-3">
        <SaveIndicator state={saveState} />
        {onRefresh && (
          <button onClick={doRefresh} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold"
            style={{ border: "1px solid #E7EAF3", color: "#4B5468" }} title="拉取其他裝置更新的最新資料">
            <RefreshCw size={13} className={refreshing ? "animate-spin" : ""} /> 同步最新資料
          </button>
        )}
      </div>
    </div>
  );
}

/* ------------------------- Dashboard ------------------------- */

function DashboardPage({ records, branches, items, goTo }) {
  const stats = useMemo(() => {
    const totalAmount = records.reduce((s, r) => s + r.amount, 0);
    const months = [...new Set(records.map((r) => r.date.slice(0, 7)))].sort();
    const lastMonth = months[months.length - 1];
    const prevMonth = months[months.length - 2];
    const lastMonthAmt = records.filter((r) => r.date.slice(0, 7) === lastMonth).reduce((s, r) => s + r.amount, 0);
    const prevMonthAmt = records.filter((r) => r.date.slice(0, 7) === prevMonth).reduce((s, r) => s + r.amount, 0);
    const momDelta = prevMonthAmt ? ((lastMonthAmt - prevMonthAmt) / prevMonthAmt * 100).toFixed(1) : null;
    const branchesUsed = new Set(records.map((r) => r.branch)).size;
    return { totalAmount, lastMonth, lastMonthAmt, momDelta, branchesUsed };
  }, [records]);

  const branchRank = useMemo(() => {
    const m = {};
    records.forEach((r) => { m[r.branch] = (m[r.branch] || 0) + r.amount; });
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([branch, amount]) => ({ branch, amount }));
  }, [records]);

  const monthlyTrend = useMemo(() => {
    const m = {};
    records.forEach((r) => { const k = r.date.slice(0, 7); m[k] = (m[k] || 0) + r.amount; });
    return Object.entries(m).sort().map(([month, amount]) => ({ month: month.slice(5) + "月", amount: Math.round(amount / 1000) }));
  }, [records]);

  const categoryBreakdown = useMemo(() => {
    const m = {};
    records.forEach((r) => { const key = r.category || "未分類"; m[key] = (m[key] || 0) + r.amount; });
    const entries = Object.entries(m).sort((a, b) => b[1] - a[1]);
    const total = entries.reduce((s, [, v]) => s + v, 0);
    const colors = ["#2F6FED", "#7C5CFC", "#0E9F8E", "#E0932B", "#E0524B", "#64708A", "#0A6CDB"];
    return entries.slice(0, 6).map(([name, value], i) => ({ name, value: Math.round((value / total) * 100), color: colors[i % colors.length] }));
  }, [records]);

  // cost anomaly: same item, branch unit cost vs company-wide average
  const anomalies = useMemo(() => {
    const byItem = {};
    records.forEach((r) => { (byItem[r.code] = byItem[r.code] || []).push(r); });
    const results = [];
    Object.entries(byItem).forEach(([code, list]) => {
      const avg = list.reduce((s, r) => s + r.unitCost, 0) / list.length;
      const byBranch = {};
      list.forEach((r) => { (byBranch[r.branch] = byBranch[r.branch] || []).push(r.unitCost); });
      Object.entries(byBranch).forEach(([branch, costs]) => {
        const branchAvg = costs.reduce((s, c) => s + c, 0) / costs.length;
        const diffPct = ((branchAvg - avg) / avg) * 100;
        if (diffPct > 18) {
          results.push({ branch, item: list[0].item, code, branchAvg: Math.round(branchAvg), companyAvg: Math.round(avg), diffPct: diffPct.toFixed(0) });
        }
      });
    });
    return results.sort((a, b) => b.diffPct - a.diffPct).slice(0, 5);
  }, [records]);

  return (
    <div className="p-8 space-y-6">
      <div className="grid grid-cols-4 gap-4">
        <KPICard label="累計採購總額" value={stats.totalAmount.toLocaleString()} unit="元" icon={Wallet} tint="#2F6FED" />
        <KPICard label={`最近月份採購額（${stats.lastMonth || "-"}）`} value={stats.lastMonthAmt.toLocaleString()} unit="元"
          delta={stats.momDelta !== null ? `${stats.momDelta > 0 ? "+" : ""}${stats.momDelta}% MoM` : null} up={stats.momDelta > 0} icon={TrendingUp} tint="#0E9F8E" />
        <KPICard label="有進貨紀錄的分校數" value={stats.branchesUsed} unit={`/ ${branches.length} 家`} icon={Store} tint="#7C5CFC" />
        <KPICard label="進貨紀錄筆數" value={records.length.toLocaleString()} unit="筆" icon={ClipboardList} tint="#E0932B" />
      </div>

      {anomalies.length > 0 && (
        <div className="rounded-2xl p-5 cursor-pointer transition-transform hover:scale-[1.005]"
          style={{ background: "linear-gradient(120deg,#181038 0%,#2A1B5E 55%,#3A1E6E 100%)" }} onClick={() => goTo("reports")}>
          <div className="flex items-center gap-3 mb-3">
            <Sparkles size={18} color="#C9B8FF" />
            <span className="text-white font-semibold text-sm">成本異常提醒：以下分校同品項進貨單價明顯高於全公司均價</span>
          </div>
          <div className="space-y-2">
            {anomalies.map((a) => (
              <div key={a.branch + a.code} className="flex items-center gap-3 text-xs text-white/70 bg-white/5 rounded-lg px-3 py-2">
                <Badge tint="#E0524B" soft={false}>{a.branch}</Badge>
                <span className="flex-1 truncate">{a.item}</span>
                <span style={{ fontFamily: "'IBM Plex Mono', monospace" }}>該分校 NT${a.branchAvg} / 全公司均價 NT${a.companyAvg}</span>
                <span className="font-bold" style={{ color: "#FF9E9E" }}>+{a.diffPct}%</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-3 gap-5">
        <div className="col-span-2 rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <h3 className="font-bold text-[15px] mb-5">各分校採購金額排行（Top 8）</h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={branchRank} layout="vertical" margin={{ left: 10 }}>
              <CartesianGrid horizontal={false} stroke="#F1F2F7" />
              <XAxis type="number" tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
              <YAxis type="category" dataKey="branch" width={40} tick={{ fontSize: 12, fill: "#4B5468" }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} formatter={(v) => `NT$${v.toLocaleString()}`} />
              <Bar dataKey="amount" fill="#2F6FED" radius={[0, 6, 6, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <h3 className="font-bold text-[15px] mb-5">品項類別採購占比</h3>
          <ResponsiveContainer width="100%" height={170}>
            <PieChart>
              <Pie data={categoryBreakdown} dataKey="value" innerRadius={48} outerRadius={75} paddingAngle={2}>
                {categoryBreakdown.map((c) => <Cell key={c.name} fill={c.color} />)}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
          <div className="space-y-2 mt-2">
            {categoryBreakdown.map((c) => (
              <div key={c.name} className="flex items-center justify-between text-xs">
                <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full" style={{ background: c.color }} />{c.name}</div>
                <span style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="font-semibold">{c.value}%</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
        <h3 className="font-bold text-[15px] mb-5">每月採購金額趨勢（單位：千元）</h3>
        <ResponsiveContainer width="100%" height={220}>
          <LineChart data={monthlyTrend}>
            <CartesianGrid vertical={false} stroke="#F1F2F7" />
            <XAxis dataKey="month" tick={{ fontSize: 12, fill: "#8891A6" }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
            <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} />
            <Line type="monotone" dataKey="amount" stroke="#2F6FED" strokeWidth={2.5} dot={{ r: 3 }} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

/* ------------------------- Import page ------------------------- */

function parseWorkbookAOA(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: "array" });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const aoa = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null });
        resolve(aoa);
      } catch (err) { reject(err); }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
}

// Parses the "分校進貨成本大表單" wide-matrix monthly report:
// row with branch names repeated across 5-column blocks, next row with 進貨/調入/調出/調回/小計 sub-headers,
// then item rows with 產編/品名/類別/成本 in the first four columns.
function parseMonthlyWideSheet(aoa) {
  let dateStr = "", monthLabel = "";
  for (let r = 0; r < Math.min(aoa.length, 6) && !dateStr; r++) {
    for (const v of aoa[r] || []) {
      if (typeof v === "string") {
        const m = v.match(/(\d{2,3})[\/年](\d{1,2})/);
        if (m) {
          const adYear = parseInt(m[1], 10) + 1911;
          const month = String(parseInt(m[2], 10)).padStart(2, "0");
          monthLabel = `${adYear}-${month}`;
          dateStr = `${adYear}-${month}-01`;
          break;
        }
      }
    }
  }

  let subHeaderRow = -1;
  for (let r = 0; r < Math.min(aoa.length, 8); r++) {
    if ((aoa[r] || []).some((v) => v === "進貨")) { subHeaderRow = r; break; }
  }
  if (subHeaderRow === -1) {
    throw new Error("找不到「進貨」欄位標題列，請確認為分校進貨成本大表單格式");
  }
  const branchRow = aoa[subHeaderRow - 1] || [];
  const subRow = aoa[subHeaderRow] || [];

  const fixedHeaders = subRow.slice(0, 4).map((h) => String(h || "").trim());
  const codeCol = fixedHeaders.findIndex((h) => h.includes("編"));
  const titleCol = fixedHeaders.findIndex((h) => h.includes("品名") || h.includes("名稱"));
  const catCol = fixedHeaders.findIndex((h) => h.includes("類別"));
  const costCol = fixedHeaders.findIndex((h) => h.includes("成本"));

  const blocks = [];
  for (let c = 0; c < branchRow.length; c++) {
    if (subRow[c] === "進貨" && branchRow[c]) blocks.push({ name: String(branchRow[c]).trim(), col: c });
  }
  if (blocks.length === 0) throw new Error("找不到任何分校欄位區塊");

  const itemMaster = [];
  const records = [];
  for (let r = subHeaderRow + 1; r < aoa.length; r++) {
    const row = aoa[r] || [];
    const code = row[codeCol >= 0 ? codeCol : 0];
    const title = row[titleCol >= 0 ? titleCol : 1];
    if (code == null && title == null) continue;
    const category = catCol >= 0 ? row[catCol] : "";
    const cost = Number(row[costCol >= 0 ? costCol : 3]) || 0;
    itemMaster.push({ code: String(code ?? ""), title: String(title ?? ""), category: String(category ?? ""), cost });
    blocks.forEach(({ name, col }) => {
      const purchase = Number(row[col]) || 0;      // 進貨
      const returned = Number(row[col + 3]) || 0;  // 調回(總務收回，視同進貨減項)
      const qty = purchase - returned;              // 調入/調出為分校間庫存調撥，不計入
      if (qty > 0) {
        records.push({
          branch: name, code: String(code ?? ""), item: String(title ?? ""),
          category: String(category ?? ""), qty, unitCost: cost, amount: qty * cost,
        });
      }
    });
  }

  return { dateStr, monthLabel, branchCount: blocks.length, itemMaster, records };
}

function MonthlyImportPage({ existingRecords, onImport }) {
  const [file, setFile] = useState(null);
  const [result, setResult] = useState(null);
  const [dateOverride, setDateOverride] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const [showDuplicateModal, setShowDuplicateModal] = useState(false);
  const inputRef = useRef();

  const handleFile = async (f) => {
    setFile(f); setError(""); setStatus(""); setResult(null); setShowDuplicateModal(false);
    try {
      const aoa = await parseWorkbookAOA(f);
      const parsed = parseMonthlyWideSheet(aoa);
      setResult(parsed);
      setDateOverride(parsed.dateStr || "");
    } catch (e) {
      setError(e.message || "檔案解析失敗，請確認為分校進貨成本大表單格式（.xlsx）");
    }
  };

  const totalAmount = result ? result.records.reduce((s, r) => s + r.amount, 0) : 0;
  const alreadyImported = result && dateOverride ? existingRecords.some((r) => r.date.slice(0, 7) === dateOverride.slice(0, 7)) : false;

  const doImport = () => {
    if (!result) return;
    const finalDate = dateOverride || result.dateStr;
    const newRecords = result.records.map((r, i) => ({
      id: `IMP${Date.now()}${i}`, date: finalDate, branch: r.branch, code: r.code, item: r.item,
      category: r.category, vendor: "", qty: r.qty, unitCost: r.unitCost, amount: r.amount,
    }));
    onImport(newRecords, result.itemMaster);
    setStatus(`成功匯入 ${newRecords.length} 筆進貨紀錄（${finalDate.slice(0, 7)}），並同步更新 ${result.itemMaster.length} 筆品項主檔`);
    setFile(null); setResult(null); setShowDuplicateModal(false);
    if (inputRef.current) inputRef.current.value = "";
  };

  const confirmImport = () => {
    if (!result) return;
    if (alreadyImported) { setShowDuplicateModal(true); return; }
    doImport();
  };

  return (
    <div className="p-8 space-y-5">
      <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
        <h3 className="font-bold text-[15px] mb-1">每月進貨大表單匯入</h3>
        <p className="text-xs mb-5" style={{ color: "#64708A" }}>
          上傳公司匯出的「分校進貨成本大表單」（每月一份，格式如「115年7月.xlsx」），系統會自動辨識月份、各分校進貨數量與成本，
          並以「進貨－調回」（調回為總務收回，視同進貨減項）× 成本計算金額——調入/調出為分校間庫存調撥，不計入採購金額。
        </p>

        <label className="flex flex-col items-center justify-center gap-2 p-10 rounded-xl border-2 border-dashed cursor-pointer transition-colors hover:bg-[#F9FAFC]" style={{ borderColor: "#D5D9E5" }}>
          <FileUp size={26} color="#2F6FED" />
          <span className="text-sm font-medium">{file ? file.name : "點擊選擇檔案，或拖曳至此"}</span>
          <span className="text-xs" style={{ color: "#8891A6" }}>格式：每月進貨成本大表單（.xlsx）</span>
          <input ref={inputRef} type="file" accept=".xlsx,.xls" className="hidden" onChange={(e) => e.target.files[0] && handleFile(e.target.files[0])} />
        </label>

        {error && <div className="mt-4 flex items-center gap-2 text-sm font-medium" style={{ color: "#E0524B" }}><AlertTriangle size={15} /> {error}</div>}
        {status && <div className="mt-4 flex items-center gap-2 text-sm font-medium" style={{ color: "#0E9F8E" }}><CheckCircle2 size={15} /> {status}</div>}
      </div>

      {result && (
        <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <div className="grid grid-cols-4 gap-4 mb-5">
            <div className="rounded-xl p-3" style={{ background: "#F6F7FB" }}>
              <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>偵測分校數</div>
              <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-lg font-bold">{result.branchCount} 家</div>
            </div>
            <div className="rounded-xl p-3" style={{ background: "#F6F7FB" }}>
              <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>品項主檔筆數</div>
              <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-lg font-bold">{result.itemMaster.length} 筆</div>
            </div>
            <div className="rounded-xl p-3" style={{ background: "#F6F7FB" }}>
              <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>有效進貨紀錄</div>
              <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-lg font-bold">{result.records.length} 筆</div>
            </div>
            <div className="rounded-xl p-3" style={{ background: "#F6F7FB" }}>
              <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>本月採購總額</div>
              <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-lg font-bold">NT${totalAmount.toLocaleString()}</div>
            </div>
          </div>

          <div className="flex items-end gap-3 mb-4">
            <div>
              <label className="text-xs font-semibold block mb-1.5" style={{ color: "#64708A" }}>資料所屬月份（自動偵測，如有誤請手動調整）</label>
              <input type="month" value={dateOverride.slice(0, 7)} onChange={(e) => setDateOverride(`${e.target.value}-01`)}
                className="px-3 py-2 rounded-lg border text-sm outline-none" style={{ borderColor: "#E7EAF3" }} />
            </div>
            <button onClick={confirmImport} className="flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-white text-sm font-semibold" style={{ background: alreadyImported ? "#E0932B" : "#2F6FED" }}>
              <CheckCircle2 size={15} /> 確認匯入
            </button>
          </div>

          {alreadyImported && !showDuplicateModal && (
            <div className="flex items-center gap-2 text-xs mb-4 p-3 rounded-lg" style={{ color: "#E0932B", background: "#FFF8EE" }}>
              <AlertTriangle size={14} /> 系統中已有 {dateOverride.slice(0, 7)} 的進貨紀錄，點擊「確認匯入」將會再次跳出提醒讓你確認是否要繼續。
            </div>
          )}

          <div className="text-xs font-semibold mb-2" style={{ color: "#64708A" }}>預覽（前 10 筆有效進貨紀錄）</div>
          <div className="rounded-xl overflow-hidden" style={{ border: "1px solid #E7EAF3" }}>
            <table className="w-full text-xs">
              <thead>
                <tr style={{ background: "#F6F7FB" }}>
                  {["分校", "產編", "品名", "類別", "進貨數量", "成本", "金額"].map((h) => (
                    <th key={h} className="text-left px-3 py-2 font-semibold" style={{ color: "#8891A6" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {result.records.slice(0, 10).map((r, i) => (
                  <tr key={i} style={{ borderTop: "1px solid #F1F2F7" }}>
                    <td className="px-3 py-2">{r.branch}</td>
                    <td className="px-3 py-2">{r.code}</td>
                    <td className="px-3 py-2 max-w-[220px] truncate">{r.item}</td>
                    <td className="px-3 py-2">{r.category}</td>
                    <td className="px-3 py-2">{r.qty}</td>
                    <td className="px-3 py-2">{r.unitCost.toLocaleString()}</td>
                    <td className="px-3 py-2 font-semibold">{r.amount.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {showDuplicateModal && (
        <div className="fixed inset-0 z-30 flex items-center justify-center p-6" style={{ background: "rgba(16,24,43,0.4)" }} onClick={() => setShowDuplicateModal(false)}>
          <div className="w-full max-w-sm bg-white rounded-2xl p-6" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2.5 mb-3">
              <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: "#FFF3E0" }}>
                <AlertTriangle size={18} color="#E0932B" />
              </div>
              <h3 className="font-bold text-[15px]">{dateOverride.slice(0, 7)} 已有匯入紀錄</h3>
            </div>
            <p className="text-xs leading-5 mb-5" style={{ color: "#64708A" }}>
              系統中已經有 {dateOverride.slice(0, 7)} 的進貨紀錄。若繼續匯入，這批 {result?.records.length ?? 0} 筆資料會「疊加」上去，
              可能造成該月金額重複計算。請確認是否要繼續。
            </p>
            <div className="flex gap-2.5">
              <button onClick={() => setShowDuplicateModal(false)} className="flex-1 py-2.5 rounded-xl text-sm font-semibold" style={{ border: "1px solid #E7EAF3", color: "#4B5468" }}>
                取消匯入
              </button>
              <button onClick={doImport} className="flex-1 py-2.5 rounded-xl text-white text-sm font-semibold" style={{ background: "#E0932B" }}>
                確定匯入
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ------------------------- Records page ------------------------- */

function RecordsPage({ records, branches, onDelete }) {
  const [query, setQuery] = useState("");
  const [branchFilter, setBranchFilter] = useState("全部");

  const filtered = records.filter((r) =>
    (branchFilter === "全部" || r.branch === branchFilter) &&
    (query.trim() === "" || r.item.includes(query.trim()) || r.branch.includes(query.trim()) || (r.category || "").includes(query.trim()) || r.code.includes(query.trim()))
  ).sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div className="p-8">
      <div className="rounded-2xl bg-white overflow-hidden" style={{ border: "1px solid #E7EAF3" }}>
        <div className="flex items-center gap-3 p-4 flex-wrap" style={{ borderBottom: "1px solid #E7EAF3" }}>
          <div className="relative flex-1 min-w-[200px] max-w-xs">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2" color="#8891A6" />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="搜尋分校 / 品項 / 類別 / 編號"
              className="w-full pl-9 pr-3 py-2 rounded-lg border text-xs outline-none" style={{ borderColor: "#E7EAF3" }} />
          </div>
          <select value={branchFilter} onChange={(e) => setBranchFilter(e.target.value)}
            className="px-3 py-2 rounded-lg border text-xs outline-none" style={{ borderColor: "#E7EAF3" }}>
            <option value="全部">全部分校</option>
            {branches.map((b) => <option key={b.id} value={b.name}>{b.name}</option>)}
          </select>
          <span className="ml-auto text-xs" style={{ color: "#8891A6" }}>共 {filtered.length} 筆</span>
        </div>
        <div className="max-h-[600px] overflow-y-auto">
          <table className="w-full text-sm">
            <thead className="sticky top-0">
              <tr style={{ background: "#F6F7FB" }}>
                {["日期", "分校", "產編", "品項", "類別", "數量", "單價", "金額", ""].map((h) => (
                  <th key={h} className="text-left px-4 py-3 text-[11px] font-semibold" style={{ color: "#8891A6" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((r) => (
                <tr key={r.id} style={{ borderTop: "1px solid #F1F2F7" }}>
                  <td className="px-4 py-3 text-xs" style={{ color: "#64708A" }}>{r.date}</td>
                  <td className="px-4 py-3 text-xs"><Badge tint="#2F6FED">{r.branch}</Badge></td>
                  <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-4 py-3 text-xs">{r.code}</td>
                  <td className="px-4 py-3 font-medium max-w-[240px] truncate">{r.item}</td>
                  <td className="px-4 py-3 text-xs" style={{ color: "#64708A" }}>{r.category || "—"}</td>
                  <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-4 py-3 text-xs">{r.qty}</td>
                  <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-4 py-3 text-xs">{r.unitCost.toLocaleString()}</td>
                  <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-4 py-3 text-xs font-semibold">{r.amount.toLocaleString()}</td>
                  <td className="px-4 py-3"><button onClick={() => onDelete(r.id)}><Trash2 size={13} color="#E0524B" /></button></td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan={9} className="text-center py-10 text-sm" style={{ color: "#8891A6" }}>沒有符合條件的進貨紀錄</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/* ------------------------- Reports page ------------------------- */

function ReportsPage({ records, branches, items }) {
  const [tab, setTab] = useState("overview");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [branchFilter, setBranchFilter] = useState("全部");
  const [itemFilter, setItemFilter] = useState("全部");
  const [groupBy, setGroupBy] = useState("branch");
  const [compareItem, setCompareItem] = useState(items[0]?.title || "");
  const [anomalyThreshold, setAnomalyThreshold] = useState(15);

  const filtered = useMemo(() => records.filter((r) =>
    (!start || r.date >= start) && (!end || r.date <= end) &&
    (branchFilter === "全部" || r.branch === branchFilter) &&
    (itemFilter === "全部" || r.item === itemFilter)
  ), [records, start, end, branchFilter, itemFilter]);

  const totalAmount = filtered.reduce((s, r) => s + r.amount, 0);
  const totalQty = filtered.reduce((s, r) => s + r.qty, 0);

  const grouped = useMemo(() => {
    const m = {};
    filtered.forEach((r) => {
      const key = groupBy === "branch" ? r.branch : groupBy === "category" ? (r.category || "未分類") : r.item;
      if (!m[key]) m[key] = { key, qty: 0, amount: 0, count: 0 };
      m[key].qty += r.qty; m[key].amount += r.amount; m[key].count += 1;
    });
    return Object.values(m).sort((a, b) => b.amount - a.amount);
  }, [filtered, groupBy]);

  const monthlyTrend = useMemo(() => {
    const m = {};
    filtered.forEach((r) => { const k = r.date.slice(0, 7); m[k] = (m[k] || 0) + r.amount; });
    return Object.entries(m).sort().map(([month, amount]) => ({ month, amount }));
  }, [filtered]);

  // ---- ABC / Pareto analysis (by item, within filtered scope) ----
  const abc = useMemo(() => {
    const m = {};
    filtered.forEach((r) => { if (!m[r.item]) m[r.item] = { item: r.item, code: r.code, amount: 0, qty: 0 }; m[r.item].amount += r.amount; m[r.item].qty += r.qty; });
    const list = Object.values(m).sort((a, b) => b.amount - a.amount);
    const total = list.reduce((s, x) => s + x.amount, 0) || 1;
    let cum = 0;
    return list.map((x, i) => {
      cum += x.amount;
      const cumPct = (cum / total) * 100;
      const cls = cumPct <= 80 ? "A" : cumPct <= 95 ? "B" : "C";
      return { ...x, rank: i + 1, pct: (x.amount / total) * 100, cumPct, cls };
    });
  }, [filtered]);
  const classACount = abc.filter((x) => x.cls === "A").length;

  // ---- Branch x Category matrix ----
  const matrix = useMemo(() => {
    const categories = [...new Set(filtered.map((r) => r.category || "未分類"))].sort();
    const branchNames = [...new Set(filtered.map((r) => r.branch))].sort();
    const cell = {};
    let max = 0;
    filtered.forEach((r) => {
      const cat = r.category || "未分類";
      const key = `${r.branch}|${cat}`;
      cell[key] = (cell[key] || 0) + r.amount;
      if (cell[key] > max) max = cell[key];
    });
    const rowTotals = {}, colTotals = {};
    branchNames.forEach((b) => { rowTotals[b] = categories.reduce((s, c) => s + (cell[`${b}|${c}`] || 0), 0); });
    categories.forEach((c) => { colTotals[c] = branchNames.reduce((s, b) => s + (cell[`${b}|${c}`] || 0), 0); });
    return { categories, branchNames, cell, max, rowTotals, colTotals };
  }, [filtered]);

  // ---- Cost anomaly list (branch avg vs company avg, per item, within filtered scope) ----
  const anomalies = useMemo(() => {
    const byItem = {};
    filtered.forEach((r) => { (byItem[r.item] = byItem[r.item] || []).push(r); });
    const out = [];
    Object.values(byItem).forEach((list) => {
      const companyAvg = list.reduce((s, r) => s + r.unitCost, 0) / list.length;
      const byBranch = {};
      list.forEach((r) => { (byBranch[r.branch] = byBranch[r.branch] || []).push(r); });
      Object.entries(byBranch).forEach(([branch, rows]) => {
        const branchAvg = rows.reduce((s, r) => s + r.unitCost, 0) / rows.length;
        const diffPct = ((branchAvg - companyAvg) / companyAvg) * 100;
        if (Math.abs(diffPct) >= anomalyThreshold) {
          out.push({
            branch, item: list[0].item, code: list[0].code,
            branchAvg: Math.round(branchAvg), companyAvg: Math.round(companyAvg), diffPct,
            amount: rows.reduce((s, r) => s + r.amount, 0),
          });
        }
      });
    });
    return out.sort((a, b) => Math.abs(b.diffPct) - Math.abs(a.diffPct));
  }, [filtered, anomalyThreshold]);

  const compareData = useMemo(() => {
    const rows = records.filter((r) => r.item === compareItem);
    const m = {};
    rows.forEach((r) => { (m[r.branch] = m[r.branch] || []).push(r.unitCost); });
    return Object.entries(m).map(([branch, costs]) => ({
      branch, avgCost: Math.round(costs.reduce((s, c) => s + c, 0) / costs.length),
    })).sort((a, b) => b.avgCost - a.avgCost);
  }, [records, compareItem]);

  // ---- Quantity trend / seasonality analysis (uses full history, respects branch filter only) ----
  const trendScopeRecords = useMemo(() =>
    records.filter((r) => branchFilter === "全部" || r.branch === branchFilter),
    [records, branchFilter]
  );
  const monthsAvailable = useMemo(() => [...new Set(trendScopeRecords.map((r) => r.date.slice(0, 7)))].sort(), [trendScopeRecords]);

  const itemTrends = useMemo(() => {
    const byItem = {};
    trendScopeRecords.forEach((r) => {
      if (!byItem[r.item]) byItem[r.item] = { item: r.item, code: r.code, byMonth: {} };
      const ym = r.date.slice(0, 7);
      byItem[r.item].byMonth[ym] = (byItem[r.item].byMonth[ym] || 0) + r.qty;
    });
    return Object.values(byItem).map((entry) => {
      const series = monthsAvailable.map((ym) => ({ ym, qty: entry.byMonth[ym] || 0 }));
      const nonZeroMonths = series.filter((s) => s.qty > 0).length;
      let momPct = null, trend = "資料不足", suggestion = "此品項歷史資料不足 2 個月，尚無法判斷趨勢，建議持續累積每月匯入資料。";
      if (monthsAvailable.length >= 2) {
        const last = series[series.length - 1].qty;
        const prev = series[series.length - 2].qty;
        if (prev > 0) {
          momPct = ((last - prev) / prev) * 100;
          if (momPct >= 15) { trend = "上升"; suggestion = "近期需求上升，可考慮提前批量採購以取得較低單價、避免臨時缺貨。"; }
          else if (momPct <= -15) { trend = "下降"; suggestion = "近期需求下降，建議暫緩大批量採購計畫，改採小量彈性叫貨，降低庫存壓力。"; }
          else { trend = "持平"; suggestion = "近期需求穩定，維持現行採購節奏即可。"; }
        } else if (last > 0) {
          momPct = null; trend = "新增需求"; suggestion = "上月無採購、本月開始有採購，建議觀察是否為新品項或一次性需求。";
        }
      }
      return {
        item: entry.item, code: entry.code, series, monthsWithData: nonZeroMonths,
        lastQty: series[series.length - 1]?.qty || 0, momPct, trend, suggestion,
      };
    }).sort((a, b) => {
      const av = a.momPct === null ? -Infinity : Math.abs(a.momPct);
      const bv = b.momPct === null ? -Infinity : Math.abs(b.momPct);
      return bv - av;
    });
  }, [trendScopeRecords, monthsAvailable]);

  const [trendSelectedItem, setTrendSelectedItem] = useState("");
  const activeTrendItem = trendSelectedItem || itemTrends[0]?.item || "";
  const trendDetail = itemTrends.find((t) => t.item === activeTrendItem);

  const seasonality = useMemo(() => {
    if (!activeTrendItem) return [];
    const rows = trendScopeRecords.filter((r) => r.item === activeTrendItem);
    const byMonthOfYear = {};
    const years = new Set();
    rows.forEach((r) => {
      const [y, m] = r.date.split("-");
      years.add(y);
      const mm = parseInt(m, 10);
      byMonthOfYear[mm] = (byMonthOfYear[mm] || 0) + r.qty;
    });
    const numYears = years.size || 1;
    return Array.from({ length: 12 }, (_, i) => {
      const m = i + 1;
      return { month: `${m}月`, avgQty: Math.round((byMonthOfYear[m] || 0) / numYears) };
    });
  }, [trendScopeRecords, activeTrendItem]);

  const exportReport = () => {
    downloadWorkbook(`採購分析報表_${start || "起"}_${end || "迄"}.xlsx`, [
      {
        name: "篩選結果明細", headers: ["日期", "分校", "產編", "品項", "類別", "數量", "單價", "金額"],
        rows: filtered.map((r) => [r.date, r.branch, r.code, r.item, r.category, r.qty, r.unitCost, r.amount]),
      },
      {
        name: `依${groupBy === "branch" ? "分校" : groupBy === "category" ? "類別" : "品項"}彙總`,
        headers: [groupBy === "branch" ? "分校" : groupBy === "category" ? "類別" : "品項", "筆數", "數量", "金額"],
        rows: grouped.map((g) => [g.key, g.count, g.qty, g.amount]),
      },
      {
        name: "品項ABC分析", headers: ["排名", "品項", "產編", "金額", "占比%", "累計占比%", "分類"],
        rows: abc.map((a) => [a.rank, a.item, a.code, a.amount, a.pct.toFixed(1), a.cumPct.toFixed(1), a.cls]),
      },
      {
        name: "分校x類別矩陣", headers: ["分校", ...matrix.categories, "小計"],
        rows: matrix.branchNames.map((b) => [b, ...matrix.categories.map((c) => matrix.cell[`${b}|${c}`] || 0), matrix.rowTotals[b]]),
      },
      {
        name: "成本異常清單", headers: ["分校", "品項", "產編", "分校均價", "全公司均價", "差異%", "分校採購金額"],
        rows: anomalies.map((a) => [a.branch, a.item, a.code, a.branchAvg, a.companyAvg, a.diffPct.toFixed(1), a.amount]),
      },
      {
        name: "採購量趨勢分析", headers: ["品項", "產編", ...monthsAvailable, "最近月變化%", "趨勢", "建議"],
        rows: itemTrends.map((t) => [
          t.item, t.code, ...t.series.map((s) => s.qty),
          t.momPct === null ? "" : t.momPct.toFixed(1), t.trend, t.suggestion,
        ]),
      },
    ]);
  };

  const heat = (v) => {
    if (!v || matrix.max === 0) return "transparent";
    const alpha = 0.08 + (v / matrix.max) * 0.55;
    return `rgba(47,111,237,${alpha.toFixed(2)})`;
  };

  const TABS = [
    ["overview", "總覽"],
    ["abc", "ABC / 帕累托分析"],
    ["matrix", "分校 × 類別矩陣"],
    ["anomaly", `成本異常清單 (${anomalies.length})`],
    ["trend", "採購量趨勢 / 季節分析"],
    ["compare", "單一品項分校比較"],
  ];

  return (
    <div className="p-8 space-y-5">
      <div className="rounded-2xl p-5 bg-white" style={{ border: "1px solid #E7EAF3" }}>
        <div className="flex flex-wrap items-end gap-3">
          <div>
            <label className="text-xs font-semibold block mb-1.5" style={{ color: "#64708A" }}>起始日期</label>
            <input type="date" value={start} onChange={(e) => setStart(e.target.value)} className="px-3 py-2 rounded-lg border text-xs outline-none" style={{ borderColor: "#E7EAF3" }} />
          </div>
          <div>
            <label className="text-xs font-semibold block mb-1.5" style={{ color: "#64708A" }}>結束日期</label>
            <input type="date" value={end} onChange={(e) => setEnd(e.target.value)} className="px-3 py-2 rounded-lg border text-xs outline-none" style={{ borderColor: "#E7EAF3" }} />
          </div>
          <div>
            <label className="text-xs font-semibold block mb-1.5" style={{ color: "#64708A" }}>分校</label>
            <select value={branchFilter} onChange={(e) => setBranchFilter(e.target.value)} className="px-3 py-2 rounded-lg border text-xs outline-none w-32" style={{ borderColor: "#E7EAF3" }}>
              <option value="全部">全部分校</option>
              {branches.map((b) => <option key={b.id} value={b.name}>{b.name}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-semibold block mb-1.5" style={{ color: "#64708A" }}>品項</label>
            <select value={itemFilter} onChange={(e) => setItemFilter(e.target.value)} className="px-3 py-2 rounded-lg border text-xs outline-none w-48" style={{ borderColor: "#E7EAF3" }}>
              <option value="全部">全部品項</option>
              {items.map((it) => <option key={it.id} value={it.title}>{it.title}</option>)}
            </select>
          </div>
          <button onClick={exportReport} className="flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-white text-xs font-semibold ml-auto" style={{ background: "#0E9F8E" }}>
            <FileDown size={14} /> 匯出完整分析報表
          </button>
        </div>

        <div className="grid grid-cols-3 gap-4 mt-5">
          <div className="rounded-xl p-4" style={{ background: "#F6F7FB" }}>
            <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>篩選後總金額</div>
            <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-xl font-bold">NT$ {totalAmount.toLocaleString()}</div>
          </div>
          <div className="rounded-xl p-4" style={{ background: "#F6F7FB" }}>
            <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>總數量</div>
            <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-xl font-bold">{totalQty.toLocaleString()}</div>
          </div>
          <div className="rounded-xl p-4" style={{ background: "#F6F7FB" }}>
            <div className="text-[11px] mb-1" style={{ color: "#8891A6" }}>篩選筆數</div>
            <div style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-xl font-bold">{filtered.length.toLocaleString()}</div>
          </div>
        </div>
      </div>

      <div className="flex items-center gap-2 flex-wrap">
        {TABS.map(([k, l]) => (
          <button key={k} onClick={() => setTab(k)} className="px-3.5 py-1.5 rounded-full text-xs font-semibold"
            style={{ background: tab === k ? "#10213D" : "#fff", color: tab === k ? "#fff" : "#4B5468", border: tab === k ? "none" : "1px solid #E7EAF3" }}>
            {l}
          </button>
        ))}
      </div>

      {tab === "overview" && (
        <div className="space-y-5">
          <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
            <div className="flex items-center gap-2 mb-3">
              <span className="text-xs font-semibold" style={{ color: "#64708A" }}>彙總依據</span>
              {[["branch", "依分校"], ["item", "依品項"], ["category", "依類別"]].map(([k, l]) => (
                <button key={k} onClick={() => setGroupBy(k)} className="px-3 py-1.5 rounded-full text-xs font-semibold"
                  style={{ background: groupBy === k ? "#10213D" : "#fff", color: groupBy === k ? "#fff" : "#4B5468", border: groupBy === k ? "none" : "1px solid #E7EAF3" }}>
                  {l}
                </button>
              ))}
            </div>
            <ResponsiveContainer width="100%" height={260}>
              <BarChart data={grouped.slice(0, 12)}>
                <CartesianGrid vertical={false} stroke="#F1F2F7" />
                <XAxis dataKey="key" tick={{ fontSize: 10, fill: "#8891A6" }} axisLine={false} tickLine={false} interval={0} angle={-25} textAnchor="end" height={60} />
                <YAxis tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} formatter={(v) => `NT$${v.toLocaleString()}`} />
                <Bar dataKey="amount" fill="#2F6FED" radius={[6, 6, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>

          {monthlyTrend.length > 1 && (
            <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
              <h3 className="font-bold text-[15px] mb-4">篩選範圍內月度趨勢</h3>
              <ResponsiveContainer width="100%" height={220}>
                <LineChart data={monthlyTrend}>
                  <CartesianGrid vertical={false} stroke="#F1F2F7" />
                  <XAxis dataKey="month" tick={{ fontSize: 12, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                  <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} formatter={(v) => `NT$${v.toLocaleString()}`} />
                  <Line type="monotone" dataKey="amount" stroke="#2F6FED" strokeWidth={2.5} dot={{ r: 3 }} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>
      )}

      {tab === "abc" && (
        <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <div className="flex items-center gap-2.5 mb-1">
            <Sparkles size={16} color="#7C5CFC" />
            <h3 className="font-bold text-[15px]">ABC / 帕累托分析</h3>
          </div>
          <p className="text-xs mb-5" style={{ color: "#64708A" }}>
            前 <b>{classACount}</b> 項品項（佔全部 {abc.length} 項品項的 {abc.length ? ((classACount / abc.length) * 100).toFixed(0) : 0}%）貢獻了約 80% 的採購金額（A 級品項）——這些是成本控管最該優先關注的品項。
          </p>
          <ResponsiveContainer width="100%" height={300}>
            <ComposedChart data={abc.slice(0, 15)} margin={{ left: 10, right: 10 }}>
              <CartesianGrid vertical={false} stroke="#F1F2F7" />
              <XAxis dataKey="item" tick={{ fontSize: 9, fill: "#8891A6" }} axisLine={false} tickLine={false} interval={0} angle={-30} textAnchor="end" height={90} />
              <YAxis yAxisId="left" tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
              <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} domain={[0, 100]} unit="%" />
              <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} />
              <Bar yAxisId="left" dataKey="amount" fill="#2F6FED" radius={[6, 6, 0, 0]} name="採購金額" />
              <Line yAxisId="right" type="monotone" dataKey="cumPct" stroke="#E0524B" strokeWidth={2.5} dot={{ r: 3 }} name="累計占比%" />
            </ComposedChart>
          </ResponsiveContainer>

          <div className="mt-5 max-h-96 overflow-y-auto rounded-xl" style={{ border: "1px solid #E7EAF3" }}>
            <table className="w-full text-xs">
              <thead className="sticky top-0">
                <tr style={{ background: "#F6F7FB" }}>
                  {["排名", "品項", "金額", "占比", "累計占比", "分類"].map((h) => (
                    <th key={h} className="text-left px-3 py-2 font-semibold" style={{ color: "#8891A6" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {abc.map((a) => (
                  <tr key={a.item} style={{ borderTop: "1px solid #F1F2F7" }}>
                    <td className="px-3 py-2">{a.rank}</td>
                    <td className="px-3 py-2 max-w-[280px] truncate">{a.item}</td>
                    <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-3 py-2">{a.amount.toLocaleString()}</td>
                    <td className="px-3 py-2">{a.pct.toFixed(1)}%</td>
                    <td className="px-3 py-2">{a.cumPct.toFixed(1)}%</td>
                    <td className="px-3 py-2"><Badge tint={a.cls === "A" ? "#E0524B" : a.cls === "B" ? "#E0932B" : "#64708A"}>{a.cls}</Badge></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === "matrix" && (
        <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <h3 className="font-bold text-[15px] mb-1">分校 × 類別採購金額矩陣</h3>
          <p className="text-xs mb-4" style={{ color: "#64708A" }}>顏色越深代表該分校在該類別的採購金額越高，可快速看出各分校的採購結構差異</p>
          <div className="overflow-auto max-h-[560px] rounded-xl" style={{ border: "1px solid #E7EAF3" }}>
            <table className="text-xs" style={{ borderCollapse: "collapse" }}>
              <thead className="sticky top-0 z-10">
                <tr style={{ background: "#F6F7FB" }}>
                  <th className="text-left px-3 py-2 font-semibold sticky left-0" style={{ color: "#8891A6", background: "#F6F7FB" }}>分校</th>
                  {matrix.categories.map((c) => (
                    <th key={c} className="text-center px-3 py-2 font-semibold whitespace-nowrap" style={{ color: "#8891A6" }}>{c}</th>
                  ))}
                  <th className="text-right px-3 py-2 font-semibold" style={{ color: "#8891A6" }}>小計</th>
                </tr>
              </thead>
              <tbody>
                {matrix.branchNames.map((b) => (
                  <tr key={b} style={{ borderTop: "1px solid #F1F2F7" }}>
                    <td className="px-3 py-2 font-medium sticky left-0 bg-white whitespace-nowrap">{b}</td>
                    {matrix.categories.map((c) => {
                      const v = matrix.cell[`${b}|${c}`] || 0;
                      return (
                        <td key={c} className="text-center px-3 py-2 whitespace-nowrap" style={{ background: heat(v), fontFamily: "'IBM Plex Mono', monospace" }}>
                          {v ? v.toLocaleString() : "—"}
                        </td>
                      );
                    })}
                    <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-right px-3 py-2 font-semibold">{matrix.rowTotals[b].toLocaleString()}</td>
                  </tr>
                ))}
                <tr style={{ borderTop: "2px solid #E7EAF3", background: "#F9FAFC" }}>
                  <td className="px-3 py-2 font-bold sticky left-0" style={{ background: "#F9FAFC" }}>小計</td>
                  {matrix.categories.map((c) => (
                    <td key={c} style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-center px-3 py-2 font-bold">{matrix.colTotals[c].toLocaleString()}</td>
                  ))}
                  <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-right px-3 py-2 font-bold">{totalAmount.toLocaleString()}</td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === "anomaly" && (
        <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <div className="flex items-center justify-between mb-1 flex-wrap gap-3">
            <h3 className="font-bold text-[15px]">成本異常清單</h3>
            <div className="flex items-center gap-2">
              <span className="text-xs font-semibold" style={{ color: "#64708A" }}>差異門檻</span>
              {[10, 15, 20, 30].map((t) => (
                <button key={t} onClick={() => setAnomalyThreshold(t)} className="px-2.5 py-1 rounded-full text-xs font-semibold"
                  style={{ background: anomalyThreshold === t ? "#10213D" : "#fff", color: anomalyThreshold === t ? "#fff" : "#4B5468", border: anomalyThreshold === t ? "none" : "1px solid #E7EAF3" }}>
                  ±{t}%
                </button>
              ))}
            </div>
          </div>
          <p className="text-xs mb-4" style={{ color: "#64708A" }}>
            列出同一品項在特定分校的平均進貨單價，與該品項全公司平均單價相差超過門檻值的組合，依差異幅度排序
          </p>
          {anomalies.length === 0 ? (
            <div className="text-xs py-10 text-center" style={{ color: "#8891A6" }}>目前篩選範圍內沒有超過 ±{anomalyThreshold}% 的成本異常</div>
          ) : (
            <div className="max-h-[520px] overflow-y-auto rounded-xl" style={{ border: "1px solid #E7EAF3" }}>
              <table className="w-full text-xs">
                <thead className="sticky top-0">
                  <tr style={{ background: "#F6F7FB" }}>
                    {["分校", "品項", "分校均價", "全公司均價", "差異", "分校採購金額"].map((h) => (
                      <th key={h} className="text-left px-3 py-2 font-semibold" style={{ color: "#8891A6" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {anomalies.map((a, i) => (
                    <tr key={i} style={{ borderTop: "1px solid #F1F2F7" }}>
                      <td className="px-3 py-2"><Badge tint="#2F6FED">{a.branch}</Badge></td>
                      <td className="px-3 py-2 max-w-[260px] truncate">{a.item}</td>
                      <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-3 py-2">NT${a.branchAvg}</td>
                      <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-3 py-2">NT${a.companyAvg}</td>
                      <td className="px-3 py-2 font-bold" style={{ color: a.diffPct > 0 ? "#E0524B" : "#0E9F8E" }}>{a.diffPct > 0 ? "+" : ""}{a.diffPct.toFixed(0)}%</td>
                      <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-3 py-2">{a.amount.toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {tab === "trend" && (
        <div className="space-y-5">
          <div className="rounded-2xl p-5 flex items-start gap-3" style={{ background: "#181038" }}>
            <Calendar size={18} color="#C9B8FF" className="mt-0.5 shrink-0" />
            <div className="text-white/70 text-xs leading-6">
              分析各品項「月度採購數量」的變化，找出需求上升或下降的品項，作為批量採購或暫緩採購的判斷依據。
              目前系統累積了 <b className="text-white">{monthsAvailable.length}</b> 個月的資料
              （{monthsAvailable[0] || "-"} ～ {monthsAvailable[monthsAvailable.length - 1] || "-"}）。
              {monthsAvailable.length < 3 && "月度趨勢至少需要 2 個月資料、季節性判斷建議累積 12 個月（涵蓋完整年度）以上才會準確，目前資料仍在累積階段，判斷僅供參考。"}
            </div>
          </div>

          <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
            <h3 className="font-bold text-[15px] mb-4">各品項採購量變化總覽</h3>
            <div className="max-h-[420px] overflow-y-auto rounded-xl" style={{ border: "1px solid #E7EAF3" }}>
              <table className="w-full text-xs">
                <thead className="sticky top-0">
                  <tr style={{ background: "#F6F7FB" }}>
                    {["品項", "最近月採購量", "月變化", "趨勢判斷", "建議動作"].map((h) => (
                      <th key={h} className="text-left px-3 py-2 font-semibold" style={{ color: "#8891A6" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {itemTrends.map((t) => {
                    const tint = t.trend === "上升" ? "#E0524B" : t.trend === "下降" ? "#0E9F8E" : t.trend === "新增需求" ? "#7C5CFC" : "#64708A";
                    return (
                      <tr key={t.item} className="cursor-pointer hover:bg-[#F9FAFC]" style={{ borderTop: "1px solid #F1F2F7", background: activeTrendItem === t.item ? "#F0F4FF" : "transparent" }}
                        onClick={() => setTrendSelectedItem(t.item)}>
                        <td className="px-3 py-2 max-w-[260px] truncate font-medium">{t.item}</td>
                        <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-3 py-2">{t.lastQty}</td>
                        <td style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="px-3 py-2 font-semibold" style={{ color: t.momPct > 0 ? "#E0524B" : t.momPct < 0 ? "#0E9F8E" : "#64708A" }}>
                          {t.momPct === null ? "—" : `${t.momPct > 0 ? "+" : ""}${t.momPct.toFixed(0)}%`}
                        </td>
                        <td className="px-3 py-2"><Badge tint={tint}>{t.trend}</Badge></td>
                        <td className="px-3 py-2 max-w-[320px] truncate" style={{ color: "#64708A" }}>{t.suggestion}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>

          {trendDetail && (
            <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
              <div className="flex items-center justify-between flex-wrap gap-3 mb-1">
                <h3 className="font-bold text-[15px]">品項採購量細部走勢</h3>
                <select value={activeTrendItem} onChange={(e) => setTrendSelectedItem(e.target.value)} className="px-3 py-2 rounded-lg border text-xs outline-none w-72" style={{ borderColor: "#E7EAF3" }}>
                  {itemTrends.map((t) => <option key={t.item} value={t.item}>{t.item}</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2 mb-4">
                <Badge tint={trendDetail.trend === "上升" ? "#E0524B" : trendDetail.trend === "下降" ? "#0E9F8E" : "#64708A"}>{trendDetail.trend}</Badge>
                <span className="text-xs" style={{ color: "#64708A" }}>{trendDetail.suggestion}</span>
              </div>

              <div className="text-xs font-semibold mb-2" style={{ color: "#64708A" }}>月度採購數量（依實際匯入月份）</div>
              <ResponsiveContainer width="100%" height={220}>
                <BarChart data={trendDetail.series}>
                  <CartesianGrid vertical={false} stroke="#F1F2F7" />
                  <XAxis dataKey="ym" tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                  <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} formatter={(v) => `${v} 件`} />
                  <Bar dataKey="qty" fill="#2F6FED" radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>

              <div className="text-xs font-semibold mb-2 mt-6" style={{ color: "#64708A" }}>季節性參考：各月份平均採購量（跨年度平均，資料越多年越準確）</div>
              <ResponsiveContainer width="100%" height={220}>
                <BarChart data={seasonality}>
                  <CartesianGrid vertical={false} stroke="#F1F2F7" />
                  <XAxis dataKey="month" tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                  <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} formatter={(v) => `${v} 件`} />
                  <Bar dataKey="avgQty" fill="#7C5CFC" radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>
      )}

      {tab === "compare" && (
        <div className="rounded-2xl p-6 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <h3 className="font-bold text-[15px] mb-1">單一品項分校比較</h3>
          <p className="text-xs mb-4" style={{ color: "#64708A" }}>選擇一個品項，比較各分校的平均進貨單價（不受上方篩選條件影響，涵蓋全部歷史紀錄）</p>
          <select value={compareItem} onChange={(e) => setCompareItem(e.target.value)} className="px-3 py-2 rounded-lg border text-xs outline-none mb-4 w-72" style={{ borderColor: "#E7EAF3" }}>
            {items.map((it) => <option key={it.id} value={it.title}>{it.title}</option>)}
          </select>
          {compareData.length > 0 ? (
            <ResponsiveContainer width="100%" height={Math.max(compareData.length * 28, 100)}>
              <BarChart data={compareData} layout="vertical" margin={{ left: 10 }}>
                <CartesianGrid horizontal={false} stroke="#F1F2F7" />
                <XAxis type="number" tick={{ fontSize: 11, fill: "#8891A6" }} axisLine={false} tickLine={false} />
                <YAxis type="category" dataKey="branch" width={40} tick={{ fontSize: 11, fill: "#4B5468" }} axisLine={false} tickLine={false} />
                <Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7EAF3", fontSize: 12 }} formatter={(v) => `NT$${v}`} />
                <Bar dataKey="avgCost" fill="#7C5CFC" radius={[0, 6, 6, 0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : <div className="text-xs py-6 text-center" style={{ color: "#8891A6" }}>此品項尚無進貨紀錄</div>}
        </div>
      )}
    </div>
  );
}

/* ------------------------- Base data management ------------------------- */

function BranchesTable({ branches, setBranches }) {
  const [form, setForm] = useState({ name: "", address: "", contact: "", phone: "", taxId: "", invoiceName: "" });
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({});

  const add = () => { if (!form.name.trim()) return; setBranches([...branches, { id: `${Date.now()}`, ...form }]); setForm({ name: "", address: "", contact: "", phone: "", taxId: "", invoiceName: "" }); };
  const remove = (id) => setBranches(branches.filter((b) => b.id !== id));
  const startEdit = (b) => { setEditingId(b.id); setEditForm(b); };
  const saveEdit = () => { setBranches(branches.map((b) => (b.id === editingId ? editForm : b))); setEditingId(null); };

  const exportXlsx = () => downloadWorkbook("分校清單.xlsx", [{
    name: "分校清單", headers: ["分校名稱", "地址", "聯絡人", "電話", "統編", "發票抬頭"],
    rows: branches.map((b) => [b.name, b.address, b.contact, b.phone, b.taxId || "", b.invoiceName || ""]),
  }]);

  const importXlsx = async (file) => {
    const { headers, rows } = await parseExcelFile(file);
    const iName = guessColumn(headers, ["分校", "名稱", "門市"]);
    const iAddr = guessColumn(headers, ["地址"]);
    const iContact = guessColumn(headers, ["收件人", "聯絡人"]);
    const iPhone = guessColumn(headers, ["電話"]);
    const iTax = guessColumn(headers, ["統編"]);
    const iInvoice = guessColumn(headers, ["發票"]);
    const imported = rows.filter((r) => r[iName]).map((r) => ({
      id: `${Date.now()}${Math.random()}`,
      name: String(r[iName] || "").trim(),
      address: String(r[iAddr] ?? "").replace("◆地址：", "").trim(),
      contact: String(r[iContact] ?? "").trim(),
      phone: String(r[iPhone] ?? "").trim(),
      taxId: iTax !== "" ? String(r[iTax] ?? "").trim() : "",
      invoiceName: iInvoice !== "" ? String(r[iInvoice] ?? "").trim() : "",
    }));
    setBranches([...branches, ...imported]);
  };

  return (
    <div className="rounded-2xl bg-white overflow-hidden" style={{ border: "1px solid #E7EAF3" }}>
      <div className="flex items-center gap-2.5 p-4 flex-wrap" style={{ borderBottom: "1px solid #E7EAF3" }}>
        <Building2 size={16} color="#2F6FED" />
        <span className="text-sm font-semibold">分校管理</span>
        <span className="text-xs" style={{ color: "#8891A6" }}>共 {branches.length} 筆</span>
        <div className="ml-auto flex gap-2">
          <label className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold cursor-pointer" style={{ border: "1px solid #E7EAF3", color: "#4B5468" }}>
            <FileUp size={13} /> 匯入 Excel
            <input type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={(e) => e.target.files[0] && importXlsx(e.target.files[0])} />
          </label>
          <button onClick={exportXlsx} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold" style={{ border: "1px solid #E7EAF3", color: "#4B5468" }}>
            <FileDown size={13} /> 匯出 Excel
          </button>
        </div>
      </div>

      <div className="p-4 flex flex-wrap items-center gap-2.5" style={{ background: "#F9FAFC", borderBottom: "1px solid #E7EAF3" }}>
        <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="分校名稱" className="px-3 py-2 rounded-lg border text-xs outline-none w-24" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} placeholder="地址" className="px-3 py-2 rounded-lg border text-xs outline-none w-48" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.contact} onChange={(e) => setForm({ ...form, contact: e.target.value })} placeholder="收件人/聯絡人" className="px-3 py-2 rounded-lg border text-xs outline-none w-24" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="電話" className="px-3 py-2 rounded-lg border text-xs outline-none w-28" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.taxId} onChange={(e) => setForm({ ...form, taxId: e.target.value })} placeholder="統編" className="px-3 py-2 rounded-lg border text-xs outline-none w-20" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.invoiceName} onChange={(e) => setForm({ ...form, invoiceName: e.target.value })} placeholder="發票抬頭" className="px-3 py-2 rounded-lg border text-xs outline-none w-32" style={{ borderColor: "#E7EAF3" }} />
        <button onClick={add} className="flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-xs font-semibold text-white" style={{ background: "#2F6FED" }}><Plus size={13} /> 新增</button>
      </div>

      <div className="max-h-[420px] overflow-y-auto divide-y" style={{ borderColor: "#F1F2F7" }}>
        {branches.map((b) => {
          const editing = editingId === b.id;
          return (
            <div key={b.id} className="flex items-center gap-3 px-4 py-2.5">
              {editing ? (
                <>
                  <input value={editForm.name} onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} className="px-2 py-1.5 rounded-md border text-xs w-20" style={{ borderColor: "#E7EAF3" }} />
                  <input value={editForm.address} onChange={(e) => setEditForm({ ...editForm, address: e.target.value })} className="px-2 py-1.5 rounded-md border text-xs flex-1" style={{ borderColor: "#E7EAF3" }} placeholder="地址" />
                  <input value={editForm.contact} onChange={(e) => setEditForm({ ...editForm, contact: e.target.value })} className="px-2 py-1.5 rounded-md border text-xs w-20" style={{ borderColor: "#E7EAF3" }} placeholder="收件人" />
                  <input value={editForm.phone} onChange={(e) => setEditForm({ ...editForm, phone: e.target.value })} className="px-2 py-1.5 rounded-md border text-xs w-24" style={{ borderColor: "#E7EAF3" }} placeholder="電話" />
                  <input value={editForm.taxId} onChange={(e) => setEditForm({ ...editForm, taxId: e.target.value })} className="px-2 py-1.5 rounded-md border text-xs w-16" style={{ borderColor: "#E7EAF3" }} placeholder="統編" />
                  <button onClick={saveEdit}><Save size={15} color="#0E9F8E" /></button>
                </>
              ) : (
                <>
                  <span className="font-medium text-sm w-20 shrink-0 truncate">{b.name}</span>
                  <span className="text-xs flex-1 truncate" style={{ color: b.address ? "#64708A" : "#C3C8D6" }}>{b.address || "尚未填寫地址"}</span>
                  <span className="text-xs w-20 shrink-0 truncate" style={{ color: b.contact ? "#64708A" : "#C3C8D6" }}>{b.contact || "—"}</span>
                  <span className="text-xs w-28 shrink-0 truncate" style={{ color: b.phone ? "#64708A" : "#C3C8D6" }}>{b.phone || "—"}</span>
                  <span className="text-xs w-16 shrink-0 truncate" style={{ color: b.taxId ? "#64708A" : "#C3C8D6" }}>{b.taxId || "—"}</span>
                  <button onClick={() => startEdit(b)}><Pencil size={14} color="#8891A6" /></button>
                </>
              )}
              <button onClick={() => remove(b.id)}><Trash2 size={14} color="#E0524B" /></button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ItemsTable({ items, setItems }) {
  const [form, setForm] = useState({ code: "", title: "", category: "", cost: "" });
  const [query, setQuery] = useState("");

  const add = () => { if (!form.title.trim()) return; setItems([...items, { id: `${Date.now()}`, ...form, cost: Number(form.cost) || 0 }]); setForm({ code: "", title: "", category: "", cost: "" }); };
  const remove = (id) => setItems(items.filter((b) => b.id !== id));

  const exportXlsx = () => downloadWorkbook("教材品項清單.xlsx", [{
    name: "教材品項清單", headers: ["產品編號", "品名", "類別", "成本(NT$)"],
    rows: items.map((it) => [it.code, it.title, it.category || "", it.cost]),
  }]);

  const importXlsx = async (file) => {
    const { headers, rows } = await parseExcelFile(file);
    const iCode = guessColumn(headers, ["產編", "編號"]);
    const iTitle = guessColumn(headers, ["品名", "名稱"]);
    const iCategory = guessColumn(headers, ["類別"]);
    const iCost = guessColumn(headers, ["成本"]);
    const imported = rows.filter((r) => r[iTitle]).map((r) => ({
      id: `${Date.now()}${Math.random()}`, code: String(r[iCode] ?? ""), title: String(r[iTitle] || ""),
      category: iCategory !== "" ? String(r[iCategory] ?? "") : "", cost: Number(r[iCost]) || 0,
    }));
    // upsert by code: update existing, append new
    let next = [...items];
    imported.forEach((im) => {
      const idx = im.code ? next.findIndex((x) => x.code === im.code) : -1;
      if (idx >= 0) next[idx] = { ...next[idx], ...im, id: next[idx].id };
      else next.push(im);
    });
    setItems(next);
  };

  const filtered = query.trim() ? items.filter((it) => it.title.includes(query.trim()) || it.code.includes(query.trim())) : items;

  return (
    <div className="rounded-2xl bg-white overflow-hidden" style={{ border: "1px solid #E7EAF3" }}>
      <div className="flex items-center gap-2.5 p-4 flex-wrap" style={{ borderBottom: "1px solid #E7EAF3" }}>
        <BookOpen size={16} color="#7C5CFC" />
        <span className="text-sm font-semibold">教材品項管理</span>
        <span className="text-xs" style={{ color: "#8891A6" }}>共 {items.length} 筆</span>
        <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="搜尋品名/編號" className="ml-3 px-3 py-1.5 rounded-lg border text-xs outline-none w-40" style={{ borderColor: "#E7EAF3" }} />
        <div className="ml-auto flex gap-2">
          <label className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold cursor-pointer" style={{ border: "1px solid #E7EAF3", color: "#4B5468" }}>
            <FileUp size={13} /> 匯入 Excel
            <input type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={(e) => e.target.files[0] && importXlsx(e.target.files[0])} />
          </label>
          <button onClick={exportXlsx} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold" style={{ border: "1px solid #E7EAF3", color: "#4B5468" }}>
            <FileDown size={13} /> 匯出 Excel
          </button>
        </div>
      </div>

      <div className="p-4 flex flex-wrap items-center gap-2.5" style={{ background: "#F9FAFC", borderBottom: "1px solid #E7EAF3" }}>
        <input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="產品編號" className="px-3 py-2 rounded-lg border text-xs outline-none w-24" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="品名" className="px-3 py-2 rounded-lg border text-xs outline-none w-64" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} placeholder="類別" className="px-3 py-2 rounded-lg border text-xs outline-none w-28" style={{ borderColor: "#E7EAF3" }} />
        <input value={form.cost} onChange={(e) => setForm({ ...form, cost: e.target.value })} type="number" placeholder="成本(NT$)" className="px-3 py-2 rounded-lg border text-xs outline-none w-28" style={{ borderColor: "#E7EAF3" }} />
        <button onClick={add} className="flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-xs font-semibold text-white" style={{ background: "#7C5CFC" }}><Plus size={13} /> 新增</button>
      </div>

      <div className="max-h-[420px] overflow-y-auto divide-y" style={{ borderColor: "#F1F2F7" }}>
        {filtered.map((b) => (
          <div key={b.id} className="flex items-center gap-3 px-4 py-2.5">
            <span style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-xs w-16 shrink-0">#{b.code}</span>
            <span className="font-medium text-sm flex-1 min-w-0 truncate">{b.title}</span>
            <span className="text-xs w-32 shrink-0 truncate" style={{ color: "#64708A" }}>{b.category || "—"}</span>
            <span style={{ fontFamily: "'IBM Plex Mono', monospace" }} className="text-xs w-20 text-right shrink-0">NT${Number(b.cost).toLocaleString()}</span>
            <button onClick={() => remove(b.id)}><Trash2 size={14} color="#E0524B" /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function BaseDataPage({ branches, setBranches, items, setItems }) {
  const [tab, setTab] = useState("branch");
  return (
    <div className="p-8">
      <div className="flex items-center gap-2 mb-5">
        {[["branch", `分校 (${branches.length})`], ["item", `教材品項 (${items.length})`]].map(([k, l]) => (
          <button key={k} onClick={() => setTab(k)} className="px-4 py-2 rounded-full text-xs font-semibold"
            style={{ background: tab === k ? "#10213D" : "#fff", color: tab === k ? "#fff" : "#4B5468", border: tab === k ? "none" : "1px solid #E7EAF3" }}>
            {l}
          </button>
        ))}
      </div>
      {tab === "branch" && <BranchesTable branches={branches} setBranches={setBranches} />}
      {tab === "item" && <ItemsTable items={items} setItems={setItems} />}
    </div>
  );
}

/* ------------------------- Mailing labels page ------------------------- */

function MailingLabelsPage({ branches, sender, setSender }) {
  const [selected, setSelected] = useState([]);

  const toggle = (id) => setSelected((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  const selectAll = () => setSelected(branches.map((b) => b.id));
  const clearAll = () => setSelected([]);
  const selectedBranches = branches.filter((b) => selected.includes(b.id));
  const missingAddress = selectedBranches.filter((b) => !b.address);

  return (
    <div className="p-8">
      <style>{`
        @media print {
          body * { visibility: hidden; }
          #print-labels, #print-labels * { visibility: visible; }
          #print-labels { position: absolute; left: 0; top: 0; width: 100%; }
        }
      `}</style>

      <div className="grid grid-cols-3 gap-5 print:hidden">
        <div className="rounded-2xl p-5 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <h3 className="font-bold text-[15px] mb-4">寄件人資訊</h3>
          <div className="space-y-3">
            {[["name", "姓名/公司"], ["address", "地址"], ["phone", "電話"], ["zip", "郵遞區號"]].map(([k, l]) => (
              <div key={k}>
                <label className="text-xs font-semibold block mb-1" style={{ color: "#64708A" }}>{l}</label>
                <input value={sender[k]} onChange={(e) => setSender({ ...sender, [k]: e.target.value })}
                  className="w-full px-3 py-2 rounded-lg border text-sm outline-none" style={{ borderColor: "#E7EAF3" }} />
              </div>
            ))}
          </div>
        </div>

        <div className="col-span-2 rounded-2xl p-5 bg-white" style={{ border: "1px solid #E7EAF3" }}>
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-bold text-[15px]">選擇收件分校</h3>
            <div className="flex gap-2">
              <button onClick={selectAll} className="text-xs font-semibold" style={{ color: "#2F6FED" }}>全選</button>
              <button onClick={clearAll} className="text-xs font-semibold" style={{ color: "#8891A6" }}>清除</button>
            </div>
          </div>
          <div className="grid grid-cols-3 gap-2 max-h-64 overflow-y-auto mb-4">
            {branches.map((b) => (
              <label key={b.id} className="flex items-center gap-2 p-2 rounded-lg cursor-pointer text-xs" style={{ background: selected.includes(b.id) ? "#EAF0FE" : "#F6F7FB" }}>
                <input type="checkbox" checked={selected.includes(b.id)} onChange={() => toggle(b.id)} />
                <span className="font-medium">{b.name}</span>
                {!b.address && <span style={{ color: "#E0932B" }}>（無地址）</span>}
              </label>
            ))}
          </div>
          {missingAddress.length > 0 && (
            <div className="flex items-center gap-1.5 text-xs mb-3" style={{ color: "#E0932B" }}>
              <AlertTriangle size={13} /> {missingAddress.map((b) => b.name).join("、")} 尚未填寫地址，請至「分校資料設定」補上
            </div>
          )}
          <button onClick={() => window.print()} disabled={selected.length === 0}
            className="flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-white text-sm font-semibold disabled:opacity-40" style={{ background: "#10213D" }}>
            <Printer size={15} /> 列印已選 {selected.length} 張地址條
          </button>
        </div>
      </div>

      <div id="print-labels" className="grid grid-cols-2 gap-4 mt-6">
        {selectedBranches.map((b) => (
          <div key={b.id} className="rounded-xl p-4" style={{ border: "1.5px solid #10182B", minHeight: 150, background: "#fff" }}>
            <div className="flex justify-between items-start mb-6">
              <div className="text-[10px] leading-5" style={{ color: "#4B5468" }}>
                寄件人：{sender.name || "（未設定）"}<br />
                {sender.address}<br />
                {sender.zip} {sender.phone}
              </div>
              <div className="w-14 h-14 border flex items-center justify-center text-[9px] text-center shrink-0" style={{ borderColor: "#8891A6", color: "#8891A6" }}>
                郵票黏貼處
              </div>
            </div>
            <div className="text-center">
              <div className="text-lg font-bold mb-1">{b.name} 分校 收</div>
              <div className="text-sm" style={{ color: "#4B5468" }}>{b.address || "（尚未填寫地址）"}</div>
              {b.contact && <div className="text-xs mt-1" style={{ color: "#8891A6" }}>收件人：{b.contact} {b.phone}</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ------------------------- App root ------------------------- */

const PAGE_META = {
  dashboard: ["總覽儀表板", "26 家分校採購總覽 — 金額、排行、成本異常提醒"],
  import: ["進貨匯入", "上傳每月分校進貨成本大表單，自動建檔並同步品項主檔"],
  records: ["進貨紀錄", "檢視、搜尋所有已匯入的進貨紀錄"],
  reports: ["報表分析 / 匯出", "依日期、分校、品項、類別篩選並匯出報表"],
  basedata: ["分校 / 品項資料設定", "維護分校與教材品項主檔，支援 Excel 匯入匯出"],
  labels: ["郵寄地址條列印", "設定寄件人資訊，批次列印各分校收件地址條"],
};

export default function App({ user, onSignOut }) {
  useInjectFonts();
  const [data, setData, loaded, saveState, reloadData] = useAppData(SEED);
  const [active, setActive] = useState("dashboard");

  if (!loaded) {
    return <div className="min-h-screen flex items-center justify-center" style={{ background: "#F6F7FB" }}>
      <span className="text-sm" style={{ color: "#8891A6" }}>載入中…</span>
    </div>;
  }

  const setBranches = (branches) => setData({ ...data, branches });
  const setItems = (items) => setData({ ...data, items });
  const setSender = (sender) => setData({ ...data, sender });
  const deleteRecord = (id) => setData({ ...data, records: data.records.filter((r) => r.id !== id) });

  const importMonthly = (newRecords, itemMaster) => {
    let items = [...data.items];
    itemMaster.forEach((im) => {
      if (!im.code && !im.title) return;
      const idx = im.code ? items.findIndex((x) => x.code === im.code) : -1;
      if (idx >= 0) items[idx] = { ...items[idx], title: im.title || items[idx].title, category: im.category || items[idx].category, cost: im.cost || items[idx].cost };
      else items.push({ id: `${im.code || Date.now()}${Math.random()}`, code: im.code, title: im.title, category: im.category, cost: im.cost });
    });
    setData({ ...data, items, records: [...newRecords, ...data.records] });
  };

  const [title, subtitle] = PAGE_META[active];

  return (
    <div className="min-h-screen flex" style={{ background: "#F6F7FB", fontFamily: "'Noto Sans TC', sans-serif", color: "#10182B" }}>
      <Sidebar active={active} setActive={setActive} recordCount={data.records.length} user={user} onSignOut={onSignOut} />
      <div className="flex-1 min-w-0">
        <Topbar title={title} subtitle={subtitle} saveState={saveState} onRefresh={reloadData} />
        {active === "dashboard" && <DashboardPage records={data.records} branches={data.branches} items={data.items} goTo={setActive} />}
        {active === "import" && <MonthlyImportPage existingRecords={data.records} onImport={importMonthly} />}
        {active === "records" && <RecordsPage records={data.records} branches={data.branches} onDelete={deleteRecord} />}
        {active === "reports" && <ReportsPage records={data.records} branches={data.branches} items={data.items} />}
        {active === "basedata" && <BaseDataPage branches={data.branches} setBranches={setBranches} items={data.items} setItems={setItems} />}
        {active === "labels" && <MailingLabelsPage branches={data.branches} sender={data.sender} setSender={setSender} />}
      </div>
    </div>
  );
}
